import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第二册：实践与进步 · Lesson 89 A slip of the tongue","description":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 89 A slip of the tongue","description":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动词、宾语与补足语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 88 Trapped in a mine","link":"/life/english/new-concept/book-2/unit-04/lesson-088"},"next":{"text":"第二册：实践与进步 · Lesson 90 What's for supper?","link":"/life/english/new-concept/book-2/unit-04/lesson-090"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 88 Trapped in a mine","link":"/life/english/new-concept/book-2/unit-04/lesson-088"},"next":{"text":"第二册：实践与进步 · Lesson 90 What's for supper?","link":"/life/english/new-concept/book-2/unit-04/lesson-090"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-089.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-089.md"}`),i={name:"life/english/new-concept/book-2/unit-04/lesson-089.md"};function s(l,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-89-a-slip-of-the-tongue" tabindex="-1">第二册：实践与进步 · Lesson 89 A slip of the tongue <a class="header-anchor" href="#第二册-实践与进步-·-lesson-89-a-slip-of-the-tongue" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 89 A slip of the tongue&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>公开发言时说错一个词会改变含义，及时自我纠正比掩饰更清楚；练习转述与修正。本课的语言观察是：meant to say 表原本想说，meant saying 在此不表达说话意图。mean doing 常表示“意味着做某事”，需要另一语境。完成学习后，请写一段口头自我纠正，先说明误说内容，再清楚给出正确安排。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>tongue</td><td>/tʌŋ/</td><td>n.</td><td>舌头</td><td>a slip of the tongue</td></tr><tr><td>mistake</td><td>/mɪˈsteɪk/</td><td>n.</td><td>错误</td><td>correct a mistake</td></tr><tr><td>apologise</td><td>/əˈpɒlədʒaɪz/</td><td>v.</td><td>道歉</td><td>apologise politely</td></tr><tr><td>embarrassed</td><td>/ɪmˈbærəst/</td><td>adj.</td><td>尴尬的</td><td>feel embarrassed</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>a slip of the tongue — 口误，通常不是故意说谎</li><li>correct yourself — 自我纠正，用反身代词</li></ul><h2 id="语法讲解-动词、宾语与补足语" tabindex="-1">语法讲解：动词、宾语与补足语 <a class="header-anchor" href="#语法讲解-动词、宾语与补足语" aria-label="Permalink to &quot;语法讲解：动词、宾语与补足语&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：meant to say 表原本想说，meant saying 在此不表达说话意图。mean doing 常表示“意味着做某事”，需要另一语境。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I meant to say Thursday, but I accidentally said Tuesday.</p></blockquote><p>我本想说周四，却不小心说成了周二。</p><p>meant to say 表意图，said 是实际行为，but 标出意图与结果的不一致。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 Tuesday /ˈtjuːzdeɪ/ 与 Thursday /ˈθɜːzdeɪ/，录音检查首音及元音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I meant to say Thursday, but I accidentally said Tuesday. I corrected myself before anyone wrote it down. The meeting remained on Thursday.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段口头自我纠正，先说明误说内容，再清楚给出正确安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：meant to say 表意图，said 是实际行为，but 标出意图与结果的不一致。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 to say/saying：I meant ___ Thursday.（原本想说）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to say</p><p><strong>解析：</strong> mean to do 表打算、意欲做某事。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>会议最终安排在哪天？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Thursday.</p><p><strong>解析：</strong> 纠正后保留原计划，没有改到 Tuesday。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“她向听众道歉”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She apologised to the audience.</p><p><strong>解析：</strong> apologise to 引出接受道歉的人。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动词、宾语与补足语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-088">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-090">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
